package com.examservice.infrastructure.persistence.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.*;@Entity@Table(name="exams")public class ExamEntity{@Id public UUID id;@Column(nullable=false)public String name;@Column(name="faculty_id",nullable=false)public String facultyId;@Column(name="subject_id",nullable=false)public UUID subjectId;@Column(name="matrix_id",nullable=false)public UUID matrixId;@Column(name="template_id")public UUID templateId;@Column(name="created_by",nullable=false)public UUID createdBy;@Column(name="created_at",nullable=false)public Instant createdAt;@Column(name="updated_at",nullable=false)public Instant updatedAt;@Version public long version;@OneToMany(mappedBy="exam",cascade=CascadeType.ALL,orphanRemoval=true,fetch=FetchType.EAGER)public List<ExamVersionEntity>versions=new ArrayList<>();}
